; _xcall_vector: shared target address slot for _xcall* trampolines
_xcall_vector:
    .WORD $0000
; _xcall_retval_y: Y stash across the resume's caller_ret pop
_xcall_retval_y:
    .BYTE $00

; _xcall_main: shared cross-bank trampoline for non-banked callers
_xcall_main:
    STA _xcall_vector
    STX _xcall_vector+1
    LDY #$00
    PLA
    STA ($82),Y
    INC $82
    BNE _L0199
    INC $83
_L0199:
    PLA
    STA ($82),Y
    INC $82
    BNE _L0200
    INC $83
_L0200:
    LDA $D301
    STA ($82),Y
    INC $82
    BNE _L0201
    INC $83
_L0201:
    LDA $D301
    AND #$E3
    ORA $88
    STA $D301
    LDA #>_xcall_main_resume_m1
    PHA
    LDA #<_xcall_main_resume_m1
    PHA
    LDA _xcall_vector+1
    PHA
    LDA _xcall_vector
    SEC
    SBC #$01
    PHA
    BCS _xcall_main_no_borrow
    PLA
    TAX
    PLA
    SEC
    SBC #$01
    PHA
    TXA
    PHA
_xcall_main_no_borrow:
    RTS
_xcall_main_resume_m1:
    NOP
_xcall_main_resume:
    PHA
    TXA
    PHA
    TYA
    PHA
    LDY #$00
    LDA $82
    SEC
    SBC #$01
    STA $82
    BCS _L0202
    DEC $83
_L0202:
    LDY #$00
    LDA ($82),Y
    STA $D301
    LDA $82
    SEC
    SBC #$01
    STA $82
    BCS _L0203
    DEC $83
_L0203:
    LDY #$00
    LDA ($82),Y
    STA $85
    LDA $82
    SEC
    SBC #$01
    STA $82
    BCS _L0204
    DEC $83
_L0204:
    LDY #$00
    LDA ($82),Y
    STA $84
    PLA
    STA _xcall_retval_y
    PLA
    TAX
    PLA
    STA _xcall_vector
    STX _xcall_vector+1
    LDA $85
    PHA
    LDA $84
    PHA
    LDY _xcall_retval_y
    LDA _xcall_vector
    RTS

; _xcall_cloaked_portb: target PORTB byte staged by call sites
_xcall_cloaked_portb:
    .BYTE $00
; _xcall_cloaked_saved_portb: caller's PORTB byte across the call
_xcall_cloaked_saved_portb:
    .BYTE $00
; _xcall_cloaked_caller_ret: caller's return address across the call
_xcall_cloaked_caller_ret:
    .WORD $0000

; _xcall_cloaked: cross-bank trampoline from banked → cloaked targets
_xcall_cloaked:
    LDA $D301
    STA _xcall_cloaked_saved_portb
    PLA
    STA _xcall_cloaked_caller_ret
    PLA
    STA _xcall_cloaked_caller_ret+1
    LDA _xcall_cloaked_portb
    STA $D301
    LDA #>_xcall_cloaked_resume_m1
    PHA
    LDA #<_xcall_cloaked_resume_m1
    PHA
    LDA _xcall_vector+1
    PHA
    LDA _xcall_vector
    SEC
    SBC #$01
    PHA
    BCS _xcall_cloaked_no_borrow
    PLA
    TAX
    PLA
    SEC
    SBC #$01
    PHA
    TXA
    PHA
_xcall_cloaked_no_borrow:
    RTS
_xcall_cloaked_resume_m1:
    NOP
_xcall_cloaked_resume:
    STA _xcall_vector
    STX _xcall_vector+1
    STY _xcall_retval_y
    LDA _xcall_cloaked_saved_portb
    STA $D301
    LDA _xcall_cloaked_caller_ret+1
    PHA
    LDA _xcall_cloaked_caller_ret
    PHA
    LDA _xcall_vector
    RTS

; Runtime library routines

; u16Div — unsigned 16-bit divide
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = quotient (u16), $B2,$B3 = remainder (u16)

u16Div:
    LDA #$00
    STA $B4 ; remainder lo
    STA $B5 ; remainder hi
    LDX #16
.loop:
    ASL $B0
    ROL $B1 ; shift dividend left
    ROL $B4
    ROL $B5 ; shift into remainder
    ; Compare remainder with divisor
    LDA $B4
    CMP $B2
    LDA $B5
    SBC $B3
    BCC .no_sub
    ; remainder >= divisor: subtract
    LDA $B4
    SEC
    SBC $B2
    STA $B4
    LDA $B5
    SBC $B3
    STA $B5
    INC $B0 ; set quotient bit
.no_sub:
    DEX
    BNE .loop
    LDA $B4 : STA $B2
    LDA $B5 : STA $B3
    RTS


; u16Mod — unsigned 16-bit modulus
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = remainder (u16)

u16Mod:
    JSR u16Div
    LDA $B2 : STA $B0
    LDA $B3 : STA $B1
    RTS


; u16Mul — unsigned 16-bit multiply
; Input:  $B0,$B1 = operand1 (u16 little-endian)
;         $B2,$B3 = operand2 (u16 little-endian)
; Output: $B0,$B1,$B2,$B3 = result (u32 little-endian)
;
; Method: shift-and-add (16x16 -> 32)

u16Mul:
    ; result in $B4-$B7, then copy to $B0-$B3
    LDA #$00
    STA $B4
    STA $B5
    STA $B6
    STA $B7
    LDX #16 ; 16 bits
.loop:
    LSR $B3
    ROR $B2 ; shift multiplier right
    BCC .no_add
    CLC
    LDA $B4
    ADC $B0
    STA $B4
    LDA $B5
    ADC $B1
    STA $B5
    LDA $B6
    ADC #$00
    STA $B6
    LDA $B7
    ADC #$00
    STA $B7
.no_add:
    ASL $B0
    ROL $B1 ; shift multiplicand left
    DEX
    BNE .loop
    ; Copy result
    LDA $B4 : STA $B0
    LDA $B5 : STA $B1
    LDA $B6 : STA $B2
    LDA $B7 : STA $B3
    RTS



_heap_advance_bank:
    LDA _heap_bank_cur
    BMI _hab_regC
    CMP #heap_bank_last
    BCC _hab_inc_data
    LDA #regC_heap_bank_first
    BEQ _hab_oom
    STA _heap_bank_cur
    CLC
    RTS
_hab_inc_data:
    INC _heap_bank_cur
    CLC
    RTS
_hab_regC:
    CMP #regC_heap_bank_last
    BCS _hab_oom
    INC _heap_bank_cur
    CLC
    RTS
_hab_oom:
    SEC
    RTS

_heap_setup_window:
    LDA _heap_bank_cur
    BMI _hsw_regC
    LDA #<heap_low
    STA _hp_win_lo_lo
    LDA #>heap_low
    STA _hp_win_lo_hi
    LDA #<heap_end
    STA _hp_win_end_lo
    LDA #>heap_end
    STA _hp_win_end_hi
    RTS
_hsw_regC:
    LDA #<regC_heap_low
    STA _hp_win_lo_lo
    LDA #>regC_heap_low
    STA _hp_win_lo_hi
    LDA #<regC_heap_end
    STA _hp_win_end_lo
    LDA #>regC_heap_end
    STA _hp_win_end_hi
    RTS

_heap_init:
    JSR _heap_save_caller_bank
    LDA #heap_bank_first
    STA _heap_bank_cur
_hi_bank_loop:
    LDA _heap_bank_cur
    JSR _heap_select_bank
    JSR _heap_setup_window
    LDA _hp_win_lo_lo
    STA $86
    LDA _hp_win_lo_hi
    STA $86+1

    SEC
    LDA _hp_win_end_lo
    SBC _hp_win_lo_lo
    STA _heap_init_sz
    LDA _hp_win_end_hi
    SBC _hp_win_lo_hi
    ORA #$80 ; set free flag on high byte
    STA _heap_init_sz+1

    LDY #$00
    LDA _heap_init_sz
    STA ($86),Y
    INY
    LDA _heap_init_sz+1
    STA ($86),Y

    JSR _heap_advance_bank
    BCS _hi_done
    JMP _hi_bank_loop
_hi_done:
    JMP _heap_restore_caller_bank ; tail-call: RTS through restore

_heap_init_sz:
    .BYTE $00, $00

_heap_alloc:
    JSR _heap_save_caller_bank
    LDX #$00
    JMP _ha_body
_heap_alloc16:
    JSR _heap_save_caller_bank
_ha_body:
    CLC
    ADC #$04
    STA _heap_req
    TXA
    ADC #$00
    STA _heap_req+1

    LDA #heap_bank_first
    STA _heap_bank_cur

_ha_bank_loop:
    LDA _heap_bank_cur
    JSR _heap_select_bank
    JSR _heap_setup_window

    LDA _hp_win_lo_lo
    STA $86
    LDA _hp_win_lo_hi
    STA $86+1

_ha_loop:
    LDA $86+1
    CMP _hp_win_end_hi
    BCC _ha_read
    BNE _ha_next_bank
    LDA $86
    CMP _hp_win_end_lo
    BCS _ha_next_bank

_ha_read:
    LDY #$00
    LDA ($86),Y
    STA _heap_cur_size
    INY
    LDA ($86),Y
    STA _heap_cur_hdr ; preserve raw byte (with free flag)
    AND #$7F
    STA _heap_cur_size+1

    LDA _heap_cur_hdr
    BPL _ha_advance ; allocated → skip

    LDA _heap_cur_size
    CMP _heap_req
    LDA _heap_cur_size+1
    SBC _heap_req+1
    BCC _ha_advance ; too small

    SEC
    LDA _heap_cur_size
    SBC _heap_req
    STA _heap_rem
    LDA _heap_cur_size+1
    SBC _heap_req+1
    STA _heap_rem+1

    LDA _heap_rem+1
    BNE _ha_split
    LDA _heap_rem
    CMP #$04
    BCS _ha_split

    LDY #$01
    LDA _heap_cur_size+1
    STA ($86),Y
    JMP _ha_ret

_ha_split:
    CLC
    LDA $86
    ADC _heap_req
    STA $84
    LDA $86+1
    ADC _heap_req+1
    STA $84+1

    LDY #$00
    LDA _heap_rem
    STA ($84),Y
    INY
    LDA _heap_rem+1
    ORA #$80
    STA ($84),Y

    LDY #$00
    LDA _heap_req
    STA ($86),Y
    INY
    LDA _heap_req+1
    STA ($86),Y

_ha_ret:
    LDY #$02
    LDA #$01
    STA ($86),Y ; retain lo
    INY
    LDA #$00
    STA ($86),Y ; retain hi

    CLC
    LDA $86
    ADC #$04
    STA _heap_ret_lo
    LDA $86+1
    ADC #$00
    STA _heap_ret_hi
    JSR _heap_restore_caller_bank
    LDA _heap_ret_lo
    LDX _heap_ret_hi
    LDY _heap_bank_cur
    RTS

_ha_advance:
    CLC
    LDA $86
    ADC _heap_cur_size
    STA $86
    LDA $86+1
    ADC _heap_cur_size+1
    STA $86+1
    JMP _ha_loop

_ha_next_bank:
    JSR _heap_advance_bank
    BCS _ha_oom
    JMP _ha_bank_loop

_ha_oom:
    JSR _heap_restore_caller_bank
    LDA #$00
    TAX
    TAY
    RTS

_heap_free:
    JSR _heap_save_caller_bank
    STA _heap_free_ptr
    STX _heap_free_ptr+1
    ORA _heap_free_ptr+1
    BNE _hf_not_null
    JMP _heap_restore_caller_bank

_hf_not_null:
    STY _heap_free_bank
    TYA
    JSR _heap_select_bank
    STY _heap_bank_cur
    JSR _heap_setup_window

    SEC
    LDA _heap_free_ptr
    SBC #$04
    STA $84
    LDA _heap_free_ptr+1
    SBC #$00
    STA $84+1

    LDY #$01
    LDA ($84),Y
    ORA #$80
    STA ($84),Y

    LDA _hp_win_lo_lo
    STA $86
    LDA _hp_win_lo_hi
    STA $86+1
    LDA #$00
    STA _heap_prev_ptr
    STA _heap_prev_ptr+1

_hf_walk:
    LDA $86+1
    CMP $84+1
    BNE _hf_step
    LDA $86
    CMP $84
    BEQ _hf_arrived

_hf_step:
    LDA $86
    STA _heap_prev_ptr
    LDA $86+1
    STA _heap_prev_ptr+1

    LDY #$00
    LDA ($86),Y
    STA _heap_cur_size
    INY
    LDA ($86),Y
    AND #$7F
    STA _heap_cur_size+1

    CLC
    LDA $86
    ADC _heap_cur_size
    STA $86
    LDA $86+1
    ADC _heap_cur_size+1
    STA $86+1

    CMP _hp_win_end_hi
    BCC _hf_walk
    BNE _hf_right_merge
    LDA $86
    CMP _hp_win_end_lo
    BCC _hf_walk
    JMP _hf_right_merge ; ran off end — skip merges, just bail

_hf_arrived:
    LDA _heap_prev_ptr
    ORA _heap_prev_ptr+1
    BEQ _hf_right_merge ; no left (we're at window low)

    LDA _heap_prev_ptr
    STA $86
    LDA _heap_prev_ptr+1
    STA $86+1

    LDY #$01
    LDA ($86),Y
    BPL _hf_right_merge ; prev not free

    LDY #$00
    LDA ($84),Y
    STA _heap_cur_size
    INY
    LDA ($84),Y
    AND #$7F
    STA _heap_cur_size+1

    LDY #$00
    LDA ($86),Y
    CLC
    ADC _heap_cur_size
    STA ($86),Y
    INY
    LDA ($86),Y
    AND #$7F
    ADC _heap_cur_size+1
    ORA #$80
    STA ($86),Y

    LDA $86
    STA $84
    LDA $86+1
    STA $84+1

_hf_right_merge:
    LDY #$00
    LDA ($84),Y
    STA _heap_cur_size
    INY
    LDA ($84),Y
    AND #$7F
    STA _heap_cur_size+1

    CLC
    LDA $84
    ADC _heap_cur_size
    STA $86
    LDA $84+1
    ADC _heap_cur_size+1
    STA $86+1

    CMP _hp_win_end_hi
    BCC _hf_test_right_free
    BNE _hf_free_done
    LDA $86
    CMP _hp_win_end_lo
    BCS _hf_free_done

_hf_test_right_free:
    LDY #$01
    LDA ($86),Y
    BPL _hf_free_done ; allocated, no merge

    LDY #$00
    LDA ($86),Y
    STA _heap_rem
    INY
    LDA ($86),Y
    AND #$7F
    STA _heap_rem+1

    LDY #$00
    LDA ($84),Y
    CLC
    ADC _heap_rem
    STA ($84),Y
    INY
    LDA ($84),Y
    AND #$7F
    ADC _heap_rem+1
    ORA #$80
    STA ($84),Y

_hf_free_done:
    JMP _heap_restore_caller_bank ; tail-call: RTS through restore

_heap_total_free:
    JSR _heap_save_caller_bank
    LDA #$00
    STA _heap_total_lo
    STA _heap_total_hi

    LDA #heap_bank_first
    STA _heap_bank_cur

_htf_bank_loop:
    LDA _heap_bank_cur
    JSR _heap_select_bank
    JSR _heap_setup_window

    LDA _hp_win_lo_lo
    STA $86
    LDA _hp_win_lo_hi
    STA $86+1

_htf_loop:
    LDA $86+1
    CMP _hp_win_end_hi
    BCC _htf_read
    BNE _htf_bank_done
    LDA $86
    CMP _hp_win_end_lo
    BCS _htf_bank_done

_htf_read:
    LDY #$00
    LDA ($86),Y
    STA _heap_cur_size
    INY
    LDA ($86),Y ; raw high byte, free flag in bit 7
    STA _heap_cur_hdr
    AND #$7F
    STA _heap_cur_size+1

    LDA _heap_cur_hdr
    BPL _htf_advance ; allocated → don't count

    CLC
    LDA _heap_total_lo
    ADC _heap_cur_size
    STA _heap_total_lo
    LDA _heap_total_hi
    ADC _heap_cur_size+1
    STA _heap_total_hi

_htf_advance:
    CLC
    LDA $86
    ADC _heap_cur_size
    STA $86
    LDA $86+1
    ADC _heap_cur_size+1
    STA $86+1
    JMP _htf_loop

_htf_bank_done:
    JSR _heap_advance_bank
    BCS _htf_done
    JMP _htf_bank_loop

_htf_done:
    JSR _heap_restore_caller_bank
    LDA _heap_total_lo
    LDX _heap_total_hi
    RTS

_heap_largest_free:
    JSR _heap_save_caller_bank
    LDA #$00
    STA _heap_total_lo ; reuse as running max
    STA _heap_total_hi

    LDA #heap_bank_first
    STA _heap_bank_cur

_hlf_bank_loop:
    LDA _heap_bank_cur
    JSR _heap_select_bank
    JSR _heap_setup_window

    LDA _hp_win_lo_lo
    STA $86
    LDA _hp_win_lo_hi
    STA $86+1

_hlf_loop:
    LDA $86+1
    CMP _hp_win_end_hi
    BCC _hlf_read
    BNE _hlf_bank_done
    LDA $86
    CMP _hp_win_end_lo
    BCS _hlf_bank_done

_hlf_read:
    LDY #$00
    LDA ($86),Y
    STA _heap_cur_size
    INY
    LDA ($86),Y
    STA _heap_cur_hdr
    AND #$7F
    STA _heap_cur_size+1

    LDA _heap_cur_hdr
    BPL _hlf_advance

    LDA _heap_cur_size
    CMP _heap_total_lo
    LDA _heap_cur_size+1
    SBC _heap_total_hi
    BCC _hlf_advance ; cur_size < max
    LDA _heap_cur_size
    STA _heap_total_lo
    LDA _heap_cur_size+1
    STA _heap_total_hi

_hlf_advance:
    CLC
    LDA $86
    ADC _heap_cur_size
    STA $86
    LDA $86+1
    ADC _heap_cur_size+1
    STA $86+1
    JMP _hlf_loop

_hlf_bank_done:
    JSR _heap_advance_bank
    BCS _hlf_done
    JMP _hlf_bank_loop

_hlf_done:
    JSR _heap_restore_caller_bank
    LDA _heap_total_lo
    LDX _heap_total_hi
    RTS

_heap_req:
    .BYTE $00, $00
_heap_cur_size:
    .BYTE $00, $00
_heap_cur_hdr:
    .BYTE $00
_heap_rem:
    .BYTE $00, $00
_heap_prev_ptr:
    .BYTE $00, $00
_heap_free_ptr:
    .BYTE $00, $00
_heap_free_bank:
    .BYTE $00
_heap_bank_cur:
    .BYTE $00
_hp_win_lo_lo:
    .BYTE $00
_hp_win_lo_hi:
    .BYTE $00
_hp_win_end_lo:
    .BYTE $00
_hp_win_end_hi:
    .BYTE $00
_heap_ret_lo:
    .BYTE $00
_heap_ret_hi:
    .BYTE $00
_heap_total_lo:
    .BYTE $00
_heap_total_hi:
    .BYTE $00

_heap_del_saved:
    .BYTE $00, $00
_heap_del_hdr:
    .BYTE $00, $00
_heap_del_size:
    .BYTE $00, $00
_heap_del_end:
    .BYTE $00, $00
_heap_del_cur:
    .BYTE $00, $00


; _heap_select_bank: A = 1-based bank id → bank window points at it
_heap_select_bank:
    JSR _xe_deposit_bank ; A ← PORTB bits
    STA _bank_val ; stash bits
    LDA $D301
    AND #$E3 ; preserve non-banking bits
    ORA _bank_val
    STA $D301
    RTS

; _heap_save_caller_bank: snapshot caller's bank register
_heap_save_caller_bank:
    PHA
    LDA $D301
    STA _heap_caller_bank
    PLA
    RTS

; _heap_restore_caller_bank: reselect caller's bank
_heap_restore_caller_bank:
    PHA
    LDA _heap_caller_bank
    STA $D301
    PLA
    RTS

_heap_caller_bank:
    .BYTE $00, $00

__self_bank:
    .BYTE $00

; Banked-pointer load/store helpers (per-target bank switch)
_banked_load_byte:
    LDA $D301
    STA _bank_scratch
    LDA $91 ; bank index
    STA _bank_val ; idx scratch
    TYA
    PHA ; save caller's Y
    TXA
    PHA ; save caller's X
    LDA _bank_val ; reload idx
    JSR _xe_deposit_bank ; A ← PORTB bits for this bank
    STA _bank_val
    LDA $D301
    AND #$E3 ; preserve non-banking bits
    ORA _bank_val
    STA $D301 ; volatile (bank select)
    PLA
    TAX ; restore caller's X
    PLA
    TAY ; restore caller's Y
    LDA ($8F),Y
    PHA
    LDA _bank_scratch
    STA $D301 ; volatile (bank restore)
    PLA
    RTS

_banked_store_byte:
    STA _bank_val ; save value
    LDA $D301
    STA _bank_scratch
    LDA $91 ; bank index
    STA _bank_tmp ; idx scratch
    TYA
    PHA ; save caller's Y
    TXA
    PHA ; save caller's X
    LDA _bank_tmp ; reload idx
    JSR _xe_deposit_bank
    STA _bank_tmp
    LDA $D301
    AND #$E3
    ORA _bank_tmp
    STA $D301 ; volatile (bank select)
    PLA
    TAX ; restore caller's X
    PLA
    TAY ; restore caller's Y
    LDA _bank_val
    STA ($8F),Y
    LDA _bank_scratch
    STA $D301 ; volatile (bank restore)
    LDA _bank_val
    RTS

; xe bank-index → PORTB-bits deposit
_xe_deposit_bank:
    STA _xdb_idx ; A = 0-based index
    LDA #$00
    STA _bank_tmp ; output bits
    LDY #$00
_xdb_loop:
    LDA _xe_mask_bits,Y
    BEQ _xdb_done
    STA _bank_mask ; this mask bit
    LDA _xdb_idx
    LSR A
    STA _xdb_idx
    BCC _xdb_next ; bit 0 — don't deposit
    LDA _bank_tmp
    ORA _bank_mask
    STA _bank_tmp
_xdb_next:
    INY
    JMP _xdb_loop
_xdb_done:
    LDA _bank_tmp
    RTS

_xe_mask_bits:
    .BYTE $04,$08,$00

; ivar (self),Y access bracket — cloaked heap-class bodies
_ivar_store_byte:
    PHA ; save value
    LDA $D301
    STA _ivar_caller_portb
    LDA _ivar_target_portb
    STA $D301 ; PORTB → receiver bank
    PLA ; restore value
    STA ($8A),Y
    PHA ; save value across PORTB restore
    LDA _ivar_caller_portb
    STA $D301
    PLA
    RTS

_ivar_load_byte:
    LDA $D301
    STA _ivar_caller_portb
    LDA _ivar_target_portb
    STA $D301 ; PORTB → receiver bank
    LDA ($8A),Y
    STA _ivar_load_result
    LDA _ivar_caller_portb
    STA $D301
    LDA _ivar_load_result
    RTS

_bank_scratch:
    .BYTE $00
_bank_val:
    .BYTE $00
_bank_tmp:
    .BYTE $00
_bank_mask:
    .BYTE $00
_xdb_idx:
    .BYTE $00
_ivar_caller_portb:
    .BYTE $00
_ivar_dep_scratch:
    .BYTE $00
_ivar_load_result:
    .BYTE $00
_ivar_offset_save:
    .BYTE $00
_ivar_target_portb:
    .BYTE $00
_cloaked_bracket_portb:
    .BYTE $00
_cloak_retval_lo:
    .BYTE $00
_cloak_retval_hi:
    .BYTE $00

; Cloaked region 'lib' (bank none, $4000-$7FFF)
    .CLOAKED_SEGMENT $4000 none

; Function _printfHexU16
_fn__printfHexU16:
